import pyomo.environ as pyo

DATA = {
    "capacity":   {0: 100, 1: 40},    # chicken per trip: mode 0 = bus, mode 1 = car
    "time":       {0: 2.0, 1: 1.5},   # hours per trip
    "bus_max_trips": 10,              # at most 10 bus trips
    "car_trip_fraction": 0.6,         # at least 60% of trips must be by car
    "total_chicken": 1200,            # number of chicken to transport
    "bus_index": 0,
    "car_index": 1,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of transport modes: 0 = bus, 1 = car
    model.J = pyo.Set(initialize=[d["bus_index"], d["car_index"]])

    # Decision: number of trips of each mode
    def trips_bounds(m, j):
        if j == d["bus_index"]:
            return (0, d["bus_max_trips"])
        return (0, None)

    model.x = pyo.Var(model.J, domain=pyo.NonNegativeIntegers, bounds=trips_bounds)

    # Objective: minimize total time (hours) taken
    def obj_rule(m):
        return sum(d["time"][j] * m.x[j] for j in m.J)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: meet chicken transport requirement
    def demand_rule(m):
        return sum(d["capacity"][j] * m.x[j] for j in m.J) >= d["total_chicken"]

    model.demand = pyo.Constraint(rule=demand_rule)

    # Constraint: at least 60% of the trips must be by car
    def car_share_rule(m):
        bus = m.x[d["bus_index"]]
        car = m.x[d["car_index"]]
        return car >= d["car_trip_fraction"] * (bus + car)

    model.car_share = pyo.Constraint(rule=car_share_rule)

    return model


